// ── LRU eviction over your own file cache ──
Future<void> evictTo(int budgetBytes) async {
  final rows = await db.query('cache_files', orderBy: 'last_access ASC');
  var used = rows.fold<int>(0, (s, r) => s + (r['size'] as int));
  for (final row in rows) {
    if (used <= budgetBytes) break;
    final file = File(row['path'] as String);
    if (await file.exists()) await file.delete();
    await db.delete('cache_files', where: 'path = ?', whereArgs: [row['path']]);
    used -= row['size'] as int;
  }
}

