class LogoutService {
  LogoutService(this._api, this._db, this._secure, this._prefs, this._push);

  Future<void> logout() async {
    try {
      await _api.revokeSession();            // best effort, may fail offline
    } catch (_) {}

    await _push.deleteToken();               // stop notifications for this user
    await _secure.deleteAll();               // tokens
    await _db.wipeUserData();                // rows + pending mutation queue
    await _clearUserPrefs();                 // keep theme and locale

    PaintingBinding.instance.imageCache.clear();
    PaintingBinding.instance.imageCache.clearLiveImages();
    await imageCacheManager.emptyCache();    // cached_network_image on disk
    await WebViewCookieManager().clearCookies();
    await FlutterLocalNotificationsPlugin().cancelAll();

    await FirebaseCrashlytics.instance.setUserIdentifier('');
    await analytics.reset();

    await di.resetUserScope();               // drop singletons holding the user
  }

  Future<void> _clearUserPrefs() async {
    for (final key in _prefs.getKeys().where((k) => k.startsWith('user.'))) {
      await _prefs.remove(key);
    }
  }
}

