// A copy taken while WAL is active is missing the newest rows unless you
// checkpoint first — the usual reason an exported database "looks stale".
Future<File> exportDatabaseForInspection(Database db) async {
  await db.execute('PRAGMA wal_checkpoint(TRUNCATE)');
  final out = File('${(await getTemporaryDirectory()).path}/export.db');
  return File(db.path).copy(out.path);
}

