enum Priority { low, normal, high }

class Task {
  Task({this.id, required this.title, required this.done,
        required this.dueAt, required this.priority});

  final int? id;
  final String title;
  final bool done;
  final DateTime dueAt;
  final Priority priority;

  // ❌ throws "Invalid argument: Instance of 'DateTime'" — and index is fragile
  // Map<String, Object?> toMap() =>
  //     {'title': title, 'done': done, 'due_at': dueAt, 'priority': priority.index};

  // ✅ every value is num / String / Uint8List / null
  Map<String, Object?> toMap() => {
        'id': id,
        'title': title,
        'done': done ? 1 : 0,
        'due_at': dueAt.toUtc().millisecondsSinceEpoch, // UTC, so it sorts
        'priority': priority.name,                      // name, not index
      };

  factory Task.fromMap(Map<String, Object?> m) => Task(
        id: m['id'] as int?,
        title: m['title'] as String,
        done: (m['done'] as int? ?? 0) == 1,            // NULL is not 0
        dueAt: DateTime.fromMillisecondsSinceEpoch(
            m['due_at'] as int, isUtc: true).toLocal(),
        priority: Priority.values.byName(m['priority'] as String),
      );
}

