const _secure = FlutterSecureStorage(
  iOptions: IOSOptions(accessibility: KeychainAccessibility.first_unlock),
);

Future<Database> openStore() async {
  // Application Support: backed up, and not purged the way Caches is.
  final path = p.join((await getApplicationSupportDirectory()).path, 'app.db');
  var key = await _secure.read(key: 'db_key');

  if (key == null && await File(path).exists()) {
    // Restored onto a new device: the files came back, the Keychain did not.
    await _resetLocalState(path, reason: 'key_missing_after_restore');
  }
  key ??= await _createAndStoreKey();

  try {
    return await openDatabase(path, password: key, version: 3,
        onCreate: _create, onUpgrade: _upgrade,
        // Backup from a newer build restored onto an older binary.
        onDowngrade: onDatabaseDowngradeDelete);
  } on DatabaseException catch (e) {
    await _resetLocalState(path, reason: 'open_failed: $e');
    return openDatabase(path, password: key, version: 3, onCreate: _create);
  }
}

Future<void> _resetLocalState(String path, {required String reason}) async {
  analytics.log('local_db_reset', {'reason': reason});
  await deleteDatabase(path);   // drop it; never try to salvage an unreadable file
  await syncCursor.reset();     // next sync re-downloads everything
}

