// ✅ decode and write on another isolate, and cross the channel once
Future<void> importFast(String jsonText) async {
  final token = RootIsolateToken.instance!;   // must be read on the UI isolate
  await Isolate.run(() async {
    // Plugins (sqflite, path_provider) only work after this line.
    BackgroundIsolateBinaryMessenger.ensureInitialized(token);

    final rows = (jsonDecode(jsonText) as List).cast<Map<String, Object?>>();
    final db = await openDatabase(await databasePath());
    await db.transaction((txn) async {
      final batch = txn.batch();
      for (final row in rows) {
        batch.insert('items', row,
            conflictAlgorithm: ConflictAlgorithm.replace);
      }
      // noResult: don't encode 50 000 insert results back across the channel
      await batch.commit(noResult: true);
    });
    await db.close();
  });
}

