// ✅ one owner: every write goes through here, and every write emits
class TaskRepository {
  TaskRepository(this._db);
  final Database _db;
  final _changes = StreamController<List<Task>>.broadcast();

  Stream<List<Task>> watchOpen() async* {
    yield await _readOpen();     // seed, or the first frame shows nothing
    yield* _changes.stream;
  }

  Future<List<Task>> _readOpen() async {
    final rows = await _db.query('tasks', where: 'done = 0', orderBy: 'due_at');
    return rows.map(Task.fromMap).toList();
  }

  // The background sync calls this too — that is why the list updates.
  Future<void> setDone(int id, bool done) async {
    await _db.update('tasks', {'done': done ? 1 : 0},
        where: 'id = ?', whereArgs: [id]);
    _changes.add(await _readOpen());
  }

  void dispose() => _changes.close();
}

