Stream<List<Task>> watchOpen() =>
    (select(tasks)..where((t) => t.done.equals(false)))
        .watch()
        .distinct(listEquals);   // identical results must not rebuild the list

Future<void> closeOverdue(int cutoff) =>
    customUpdate('UPDATE tasks SET done = 1 WHERE due_at < ?',
        variables: [Variable.withInt(cutoff)],
        updates: {tasks});       // without `updates`, no stream ever fires

// One-way migration: at most once per install, resumable, verified.
Future<void> migrateNotesToSql(Database db, Box<Note> box) async {
  final done = Sqflite.firstIntValue(await db.rawQuery(
      "SELECT value FROM meta WHERE key = 'notes_migrated'"));
  if (done == 1) return;

  final keys = box.keys.toList();
  for (var i = 0; i < keys.length; i += 500) {
    final chunk = keys.skip(i).take(500).toList();
    final isLast = i + 500 >= keys.length;

    await db.transaction((txn) async {
      final batch = txn.batch();
      for (final k in chunk) {
        final note = box.get(k);
        if (note == null || note.deleted) continue;   // don't migrate garbage
        batch.insert('notes', note.toMap(),
            conflictAlgorithm: ConflictAlgorithm.replace); // re-run is a no-op
      }
      await batch.commit(noResult: true);
      if (isLast) {
        // Marker in the SAME transaction as the last chunk, or a kill here
        // makes the next launch copy everything again.
        await txn.insert('meta', {'key': 'notes_migrated', 'value': 1},
            conflictAlgorithm: ConflictAlgorithm.replace);
      }
    });
  }

  final after = Sqflite.firstIntValue(
      await db.rawQuery('SELECT COUNT(*) FROM notes'));
  analytics.log('migrate_notes', {'from': box.length, 'to': after ?? 0});
  // The box file stays until a later release proves the migration worked.
}

// Off the UI isolate, behind a progress screen, guarded against re-entry.
final _migrationLock = Lock();
Future<void> runMigrations(Database db, Box<Note> box) =>
    _migrationLock.synchronized(() => migrateNotesToSql(db, box));

@pragma('vm:entry-point')
Future<void> onBackgroundMessage(RemoteMessage message) async {
  await Firebase.initializeApp();

  // ❌ the UI isolate loaded its map at launch and will never see this write
  // final prefs = await SharedPreferences.getInstance();
  // await prefs.setInt('unread', (prefs.getInt('unread') ?? 0) + 1);

  // ✅ no Dart-side cache: every call hits DataStore / UserDefaults
  final prefs = SharedPreferencesAsync();
  await prefs.setInt('unread', (await prefs.getInt('unread') ?? 0) + 1);

  // ✅ or write where the truth lives natively and both isolates share it
  final db = await openDatabase(await databasePath());
  await db.insert('inbox', {
    'id': message.messageId,
    'at': DateTime.now().toUtc().millisecondsSinceEpoch,
  }, conflictAlgorithm: ConflictAlgorithm.ignore);
  await db.close();
}

// Still on the legacy API? Drop the stale map when the app comes back.
class _AppState extends State<App> with WidgetsBindingObserver {
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      prefs.reload().then((_) => setState(() {}));
    }
  }
}

// Any isolate you spawn yourself: register the messenger before any plugin call.
final token = RootIsolateToken.instance!;
await Isolate.run(() async {
  BackgroundIsolateBinaryMessenger.ensureInitialized(token);
  final db = await openDatabase(await databasePath());
  await db.delete('inbox', where: 'at < ?', whereArgs: [cutoff]);
  await db.close();
});

Future<Database> openWithRecovery() async {
  // Application Support, not Caches: the OS may delete Caches while it is open.
  final path = p.join((await getApplicationSupportDirectory()).path, 'app.db');
  try {
    final db = await openDatabase(path,
        version: 4, onCreate: _create, onUpgrade: _upgrade);
    if (await lastRunCrashed()) {
      final rows = await db.rawQuery('PRAGMA quick_check'); // whole-file read
      final result = rows.first.values.first;
      if (result != 'ok') {
        await db.close();
        await _quarantine(path, 'quick_check: $result');
        return openDatabase(path, version: 4, onCreate: _create);
      }
    }
    return db;
  } on DatabaseException catch (e, s) {
    await _quarantine(path, e.toString(), s);
    return openDatabase(path, version: 4, onCreate: _create);
  }
}

Future<void> _quarantine(String path, String message, [StackTrace? s]) async {
  final file = File(path);
  final stat = await file.exists() ? await file.stat() : null;

  FirebaseCrashlytics.instance.recordError(message, s, information: [
    DiagnosticsProperty('sqlite', message),     // carries the extended result code
    DiagnosticsProperty('sizeBytes', stat?.size),
    DiagnosticsProperty('dir', p.dirname(path)),
  ]);

  // Move it aside instead of repairing it; keep it for this session in case
  // support asks. The -wal and -shm siblings must go with it.
  final stamp = DateTime.now().toUtc().millisecondsSinceEpoch;
  for (final suffix in ['', '-wal', '-shm']) {
    final f = File('$path$suffix');
    if (await f.exists()) await f.rename('$path.corrupt.$stamp$suffix');
  }
  await syncCursor.reset();   // next sync re-downloads everything
}
